776	  domi::Status name_ret = model_helper.GetBaseNameFromFileName(om_name, graph_name);
777	  if (name_ret != SUCCESS) {
778	    graph_name = kGraphDefaultName + "_" + CurrentTimeInStr();
779	  }
780	  ComputeGraphPtr compute_graph = MakeShared<ComputeGraph>(graph_name);
781	  GE_CHECK_NOTNULL(compute_graph);
