803	
804	  // parse configuration item
805	  if ((op_conf != nullptr) && (*op_conf != '\0')) {
806	    // divided by ":"
807	    PropertiesManager::Instance().SetPropertyDelimiter(OP_CONF_DELIMITER);
808	    // Parsing the op_conf configuration item file
