811	        REPORT_PREDEFINED_ERR_MSG("E10003", std::vector<const char *>({"parameter", "value", "reason"}),
812	                                  std::vector<const char *>({"op_name_map", op_conf, "File content error."}));
813	        GELOGE(FAILED, "[Invoke][Init]op_name_map init failed!"); return FAILED);
