830	  if ((PreChecker::Instance().HasError()) || (run_mode == ge::RunMode::ONLY_PRE_CHECK)) {
831	    std::string check_report;
832	    ParseAtcParms(atc_params, "check_report", check_report);
833	    GE_RETURN_WITH_LOG_IF_ERROR(PreChecker::Instance().Save(check_report),
834	                                "[Invoke][Save]Generate pre-checking report failed.");
835	    GEEVENT("The pre-checking report has been saved to %s.", check_report.c_str());
836	  }
837	
838	  GE_CHK_BOOL_RET_STATUS(ret == SUCCESS, ret, "ATC model parse ret fail.");
839	
