878	  PreChecker::Instance().Clear();
879	
880	  GE_CHK_BOOL_RET_STATUS(ret == SUCCESS, ret, "[Check][State]ATC weights parse ret fail.");
881	
882	  // parser input shape range and update op shape range
883	  GE_RETURN_WITH_LOG_IF_ERROR(UpdateDynamicInputShapeRange(compute_graph, input_shape_range),
884	                              "[Update][DynamicInputShapeRange] failed");
885	
886	  return SUCCESS;
